package org.example.server.profile;
import org.example.server.persistence.JpaNativeRepository;import org.example.server.security.CurrentUser;import org.example.server.util.BusinessClock;import org.example.server.web.ConcurrentEditException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ProfileService {private final JpaNativeRepository jdbc;public ProfileService(JpaNativeRepository jdbc){this.jdbc=jdbc;}
 @Transactional(readOnly=true) public ProfileDtos.ProfileDto current(){int id=CurrentUser.require().id();List<ProfileDtos.ProfileDto> rows=jdbc.query("SELECT u.id,u.username,u.full_name,u.email,COALESCE(NULLIF(TRIM(u.role),''),'SALES'),u.department,u.branch,u.access_level,u.active,u.locked,u.mfa_enabled,COALESCE(NULLIF(u.last_login_utc,''),CAST(u.last_login AS text)),COALESCE(u.row_version,0) FROM users u WHERE u.id=?",(rs,n)->new ProfileDtos.ProfileDto(rs.getInt(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getString(8),flag(rs.getObject(9)),flag(rs.getObject(10)),flag(rs.getObject(11)),BusinessClock.toUtcText(rs.getObject(12)),rs.getLong(13)),id);if(rows.isEmpty())throw new IllegalArgumentException("User profile was not found");return rows.getFirst();}
 @Transactional public ProfileDtos.ProfileDto update(ProfileDtos.ProfileUpdate r){if(r==null||blank(r.fullName()))throw new IllegalArgumentException("Full name is required");if(blank(r.email())||!r.email().trim().matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Enter a valid email address");int id=CurrentUser.require().id();Long duplicate=jdbc.queryForObject("SELECT COUNT(*) FROM users WHERE id<>? AND LOWER(TRIM(COALESCE(email,'')))=LOWER(TRIM(?))",Long.class,id,clean(r.email()));if(duplicate!=null&&duplicate>0)throw new IllegalArgumentException("Email is already registered");int changed=jdbc.update("UPDATE users SET full_name=?,email=?,department=?,branch=?,row_version=row_version+1 WHERE id=? AND row_version=?",clean(r.fullName()),clean(r.email()),clean(r.department()),clean(r.branch()),id,r.rowVersion());if(changed!=1)throw new ConcurrentEditException("User profile");jdbc.update("INSERT INTO activity_log(entity_type,entity_id,action,detail,created_by,created_at) VALUES('USER',?,'PROFILE_UPDATED','Own profile details updated',?,?)",id,CurrentUser.require().username(),BusinessClock.nowUtcText());return current();}
 private static boolean flag(Object v){return v instanceof Boolean b?b:v instanceof Number n&&n.intValue()!=0;}private static boolean blank(String v){return v==null||v.isBlank();}private static String clean(String v){return v==null?"":v.trim();}
}
